window.renderHeroBanners=function(store){
const host=document.querySelector('.hero');if(!host)return;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const st=store.settings;const banners=store.banners??[{eyebrow:'TECNOLOGIA QUE VOLTA A FUNCIONAR',title:st.headline,highlight:st.highlight,description:st.description,image:st.heroImage,buttonText:'Preciso de assistência',destination:'services'}];
host.classList.add('hero-banner');host.dataset.carousel='';host.dataset.index='0';host.dataset.duration='3000';host.dataset.changed=String(Date.now());host.setAttribute('role','region');host.setAttribute('aria-roledescription','carrossel');host.setAttribute('aria-label','Destaques da loja');
host.innerHTML='<div class="hero-track">'+banners.map((b,i)=>{const href=b.destination==='products'?'produtos.html':b.destination==='whatsapp'?'https://wa.me/'+st.phone:'#servicos';return '<article class="hero-slide carousel-slide" '+(i?'hidden':'')+' role="group" aria-label="Destaque '+(i+1)+' de '+banners.length+'"><div class="hero-copy">'+(b.eyebrow?'<div class="eyebrow">'+esc(b.eyebrow)+'</div>':'')+'<'+(i?'h2':'h1')+' class="hero-heading">'+esc(b.title)+(b.highlight?'<br><em>'+esc(b.highlight)+'</em>':'')+'</'+(i?'h2':'h1')+'>'+(b.description?'<p>'+esc(b.description)+'</p>':'')+(b.buttonText?'<div class="hero-actions"><a class="button primary" href="'+esc(href)+'">'+esc(b.buttonText)+'</a></div>':'')+'</div><div class="hero-banner-photo"><img src="'+esc(b.image)+'" alt="'+esc(b.title)+'" '+(i?'loading="lazy"':'fetchpriority="high"')+'></div></article>'}).join('')+'</div>'+(banners.length>1?'<div class="hero-navigation"><div class="carousel-controls carousel-dots" aria-label="Selecionar destaque">'+banners.map((_,i)=>'<button type="button" data-slide-index="'+i+'" aria-label="Mostrar destaque '+(i+1)+' de '+banners.length+'" aria-pressed="'+(i===0)+'"></button>').join('')+'</div><button type="button" class="hero-pause" data-hero-pause aria-pressed="false">Pausar destaques</button></div>':'');
};
document.addEventListener('click',event=>{const button=event.target.closest('[data-hero-pause]');if(!button)return;const box=button.closest('[data-carousel]');const paused=box.dataset.paused!=='true';box.dataset.paused=String(paused);button.setAttribute('aria-pressed',String(paused));button.textContent=paused?'Reproduzir destaques':'Pausar destaques';box.dataset.changed=String(Date.now())});
